/* 重新配置 CAN 前先复位 */
CAN_DeInit(CAN1);

/* 复位后必须重新初始化，否则波特率与过滤器都是默认值 */
CAN_Init(CAN1, &CAN_InitStructure);
CAN_FilterInit(&CAN_FilterInitStructure);

CAN_InitTypeDef CAN_InitStructure;
GPIO_InitTypeDef GPIO_InitStructure;

/* 1. 开时钟：CAN1 在 APB1，GPIO 与 AFIO 在 APB2 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_CAN1, ENABLE);
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_AFIO, ENABLE);

/* 2. C8T6 上 CAN 默认在 PA11(RX)/PA12(TX)，也可重映射到 PB8/PB9 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_11;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;      /* RX 上拉输入 */
GPIO_Init(GPIOA, &GPIO_InitStructure);

GPIO_InitStructure.GPIO_Pin = GPIO_Pin_12;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;   /* TX 复用推挽 */
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 3. 需要重映射到 PB8/PB9 时才调用，否则跳过 */
/* GPIO_PinRemapConfig(GPIO_Remap1_CAN1, ENABLE); */

/* 4. 先取默认值，再改关心的字段，避免漏赋值导致随机行为 */
CAN_StructInit(&CAN_InitStructure);
CAN_InitStructure.CAN_Prescaler = 4;              /* 36MHz/4/(1+14+5)=450kbps */
CAN_InitStructure.CAN_Mode = CAN_Mode_Normal;
CAN_InitStructure.CAN_SJW = CAN_SJW_1tq;
CAN_InitStructure.CAN_BS1 = CAN_BS1_14tq;
CAN_InitStructure.CAN_BS2 = CAN_BS2_5tq;
CAN_InitStructure.CAN_ABOM = ENABLE;              /* 出错后能自动恢复 */

/* 5. 判断返回值，失败说明时钟没开或双 CAN 配置异常 */
if (CAN_Init(CAN1, &CAN_InitStructure) == CAN_InitStatus_Failed)
{
  while (1);   /* 初始化失败，通常是没开 CAN1 时钟 */
}

CAN_FilterInitTypeDef CAN_FilterInitStructure;

/* 场景：只接收标准帧 ID = 0x123，全部存到 FIFO0 */
CAN_FilterInitStructure.CAN_FilterNumber = 0;            /* 用第 0 组过滤器 */
CAN_FilterInitStructure.CAN_FilterMode = CAN_FilterMode_IdMask;
CAN_FilterInitStructure.CAN_FilterScale = CAN_FilterScale_32bit;

/* 32 位编码 = [IDE(1) | RTR(1) | EXID[28:0]]，标准帧 ID 左移 5 位 */
CAN_FilterInitStructure.CAN_FilterIdHigh = (0x123 << 5) & 0xFFFF;
CAN_FilterInitStructure.CAN_FilterIdLow  = 0x0000;

/* 掩码同样左移 5 位；|0x10 置上 IDE 位，要求 IDE=0（标准帧） */
CAN_FilterInitStructure.CAN_FilterMaskIdHigh = ((0x7FF << 5) | 0x10) & 0xFFFF;
CAN_FilterInitStructure.CAN_FilterMaskIdLow  = 0x0000;

CAN_FilterInitStructure.CAN_FilterFIFOAssignment = CAN_Filter_FIFO0;
CAN_FilterInitStructure.CAN_FilterActivation = ENABLE;
CAN_FilterInit(&CAN_FilterInitStructure);

/* 中断接收 */
CAN_ITConfig(CAN1, CAN_IT_FMP0, ENABLE);
/* 之后在 USB_LP_CAN1_RX0_IRQHandler 里判断 CAN_IT_FMP0 再 CAN_Receive */

CAN_InitTypeDef CAN_InitStructure;

CAN_StructInit(&CAN_InitStructure);   /* 先清成默认值 */

/* 只改必要的字段，其余保持默认 */
CAN_InitStructure.CAN_Prescaler = 4;
CAN_InitStructure.CAN_BS1 = CAN_BS1_14tq;
CAN_InitStructure.CAN_BS2 = CAN_BS2_5tq;

CAN_Init(CAN1, &CAN_InitStructure);

/* 仅互联型芯片需要，C8T6 请忽略本函数 */
/* 例：CAN1 用 0~13 组，CAN2 从第 14 组开始 */
/* CAN_SlaveStartBank(14); */

/* 开启时间触发模式：发送帧的最后 2 字节会被替换成时间戳 */
CAN_TTComModeCmd(CAN1, ENABLE);

CanTxMsg TxMessage;
TxMessage.DLC = 8;   /* 必须是 8，否则时间戳发不出去 */
/* Data[6]/Data[7] 不用填，硬件会写入 TIME[7:0] / TIME[15:8] */

CanTxMsg TxMessage;
uint8_t mailbox;

/* 1. 等一个空邮箱：TME0/TME1/TME2 至少一个为 1 */
while (CAN_GetFlagStatus(CAN1, CAN_FLAG_TME0) == RESET)
{
  /* 三个邮箱都忙，这里可以考虑超时退出 */
}

/* 2. 填报文 */
TxMessage.StdId = 0x123;
TxMessage.ExtId = 0x00;
TxMessage.IDE   = CAN_Id_Standard;    /* 标准帧 */
TxMessage.RTR   = CAN_RTR_Data;       /* 数据帧 */
TxMessage.DLC   = 8;
TxMessage.Data[0] = 0x11;
TxMessage.Data[1] = 0x22;
/* ... 其余字节 */

/* 3. 发送：返回邮箱号，NoMailBox 说明没排进去 */
mailbox = CAN_Transmit(CAN1, &TxMessage);
if (mailbox != CAN_TxStatus_NoMailBox)
{
  /* 4. 等发送成功。CAN_TxStatus_Pending 表示还在发，可以加超时 */
  while (CAN_TransmitStatus(CAN1, mailbox) == CAN_TxStatus_Pending)
  {
  }
}

uint8_t mail;
mail = CAN_Transmit(CAN1, &TxMessage);

if (mail != CAN_TxStatus_NoMailBox)
{
  uint32_t timeout = 100000;
  while (CAN_TransmitStatus(CAN1, mail) == CAN_TxStatus_Pending && timeout--)
  {
  }

  if (timeout == 0)
  {
    /* 超时：可能总线没接好或没有应答节点，取消这次发送 */
    CAN_CancelTransmit(CAN1, mail);
  }
  else if (CAN_TransmitStatus(CAN1, mail) == CAN_TxStatus_Failed)
  {
    /* 仲裁丢失或出错，按协议决定是否重发 */
  }
}

mail = CAN_Transmit(CAN1, &TxMessage);
if (mail != CAN_TxStatus_NoMailBox)
{
  /* 等一小会儿还没发出去就放弃 */
  if (wait_timeout(CAN1, mail) == 0)
  {
    CAN_CancelTransmit(CAN1, mail);   /* 释放邮箱，让后续报文能排进来 */
  }
}

CanRxMsg RxMessage;

void USB_LP_CAN1_RX0_IRQHandler(void)
{
  if (CAN_GetITStatus(CAN1, CAN_IT_FMP0) != RESET)
  {
    /* FIFO0 里有报文，取一帧（FIFO 号必须与过滤器分配的一致） */
    CAN_Receive(CAN1, CAN_FIFO0, &RxMessage);

    if (RxMessage.IDE == CAN_Id_Standard && RxMessage.DLC >= 1)
    {
      /* 用 RxMessage.StdId 区分报文，RxMessage.Data[0..DLC-1] 是数据 */
      process_frame(RxMessage.StdId, RxMessage.Data, RxMessage.DLC);
    }

    CAN_FIFORelease(CAN1, CAN_FIFO0);   /* 释放输出邮箱 */
  }
}

/* 轮询版：一次把所有待处理报文取完 */
while (CAN_MessagePending(CAN1, CAN_FIFO0) > 0)
{
  CAN_Receive(CAN1, CAN_FIFO0, &RxMessage);
  CAN_FIFORelease(CAN1, CAN_FIFO0);
}

/* 丢弃一帧不关心的报文：只释放不读取 */
while (CAN_MessagePending(CAN1, CAN_FIFO0) > 3)
{
  CAN_FIFORelease(CAN1, CAN_FIFO0);   /* 让 FIFO 不至于溢出 */
}

/* 主循环轮询接收 */
while (1)
{
  if (CAN_MessagePending(CAN1, CAN_FIFO0) > 0)
  {
    CAN_Receive(CAN1, CAN_FIFO0, &RxMessage);
    handle(&RxMessage);
    CAN_FIFORelease(CAN1, CAN_FIFO0);
  }
}

/* 运行期改波特率：必须先进入初始化模式 */
if (CAN_OperatingModeRequest(CAN1, CAN_OperatingMode_Initialization) == CAN_ModeStatus_Success)
{
  /* 此时可以改 CAN_BTR 或直接重调 CAN_Init */
  CAN_Init(CAN1, &CAN_InitStructure);
}

/* 回到正常工作模式，才能收发 */
CAN_OperatingModeRequest(CAN1, CAN_OperatingMode_Normal);

/* 总线空闲时进入睡眠省电 */
if (CAN_Sleep(CAN1) == CAN_Sleep_Ok)
{
  /* 睡眠中；总线上出现活动或软件调用 CAN_WakeUp 都会唤醒 */
}

/* 唤醒后回到正常模式 */
CAN_WakeUp(CAN1);

if (CAN_WakeUp(CAN1) == CAN_WakeUp_Ok)
{
  /* 已回到正常模式，可以继续收发 */
}
else
{
  /* 唤醒失败：总线被持续拉低或状态异常，检查接线与其它节点 */
}

/* 通信不上时打印错误类型定位问题 */
uint8_t lec = CAN_GetLastErrorCode(CAN1);

switch (lec)
{
  case CAN_ERRORCODE_NoErr:    /* 没有错误 */ break;
  case CAN_ERRORCODE_ACKErr:   /* 没有应答：检查收发器、终端电阻、对端节点 */ break;
  case CAN_ERRORCODE_StuffErr: /* 位填充错：波特率不一致或干扰严重 */ break;
  case CAN_ERRORCODE_BitRecessiveErr: /* 回读到的隐性与发出不符：总线短路或驱动能力不足 */ break;
  default: break;
}

/* 周期性监控总线健康度 */
if (CAN_GetReceiveErrorCounter(CAN1) > 127)
{
  /* 已进入错误被动状态：检查接线、终端电阻与对端节点 */
}

/* 发送错误计数偏高，说明总线上没人应答或线路有问题 */
if (CAN_GetLSBTransmitErrorCounter(CAN1) > 127)
{
  /* 错误被动：多半是没接对端或终端电阻缺失 */
}

if (CAN_GetFlagStatus(CAN1, CAN_FLAG_BOF) != RESET)
{
  /* 已离线（bus-off），需要 CAN_ABOM 自动恢复或重新 CAN_Init */
}

NVIC_InitTypeDef NVIC_InitStructure;

/* 1. 开 FIFO0 报文挂起中断 */
CAN_ITConfig(CAN1, CAN_IT_FMP0, ENABLE);

/* 2. 使能 NVIC 通道（C8T6 上 CAN1 接收 FIFO0 共用 USB 低优先级中断） */
NVIC_InitStructure.NVIC_IRQChannel = USB_LP_CAN1_RX0_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 1;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

void USB_LP_CAN1_RX0_IRQHandler(void)
{
  if (CAN_GetITStatus(CAN1, CAN_IT_FMP0) != RESET)
  {
    CAN_Receive(CAN1, CAN_FIFO0, &RxMessage);
    CAN_FIFORelease(CAN1, CAN_FIFO0);
  }
}

/* 发送前等一个空邮箱 */
while (CAN_GetFlagStatus(CAN1, CAN_FLAG_TME0) == RESET)
{
}
mail = CAN_Transmit(CAN1, &TxMessage);

/* 发送完成后 RQCP 会被硬件置位 */
/* 注意：读一次就被清零，别在 if 里读两遍 */
if (CAN_GetFlagStatus(CAN1, CAN_FLAG_RQCP0) != RESET)
{
  /* 邮箱 0 的发送已完成 */
}

/* FIFO 溢出后必须清标志，否则会一直读到溢出状态 */
if (CAN_GetFlagStatus(CAN1, CAN_FLAG_FOV0) != RESET)
{
  CAN_ClearFlag(CAN1, CAN_FLAG_FOV0);
  /* 这里说明接收处理太慢，需要优化（比如改成中断或提高优先级） */
}

void CAN1_SCE_IRQHandler(void)   /* 状态改变/错误中断 */
{
  if (CAN_GetITStatus(CAN1, CAN_IT_EPV) != RESET)
  {
    /* 进入错误被动：检查总线 */
    CAN_ClearITPendingBit(CAN1, CAN_IT_EPV);
  }

  if (CAN_GetITStatus(CAN1, CAN_IT_BOF) != RESET)
  {
    /* 离线，需要恢复 */
    CAN_ClearITPendingBit(CAN1, CAN_IT_BOF);
  }
}

void USB_LP_CAN1_RX0_IRQHandler(void)
{
  if (CAN_GetITStatus(CAN1, CAN_IT_FMP0) != RESET)
  {
    CAN_Receive(CAN1, CAN_FIFO0, &RxMessage);
    CAN_FIFORelease(CAN1, CAN_FIFO0);   /* 释放即清掉 FMP0 */
    handle(&RxMessage);
  }

  /* FMP0 不需要也不能用 CAN_ClearITPendingBit 清 */
}
